set-variable.value:
@{
        try {
            var jwt = ((string)context.Variables["rawBearer"]).AsJwt();
            if (jwt == null) { return ""; }
            string u = null;
            if (jwt.Claims.ContainsKey("preferred_username")) { u = jwt.Claims.GetValueOrDefault("preferred_username",""); }
            if (string.IsNullOrEmpty(u) && jwt.Claims.ContainsKey("email")) { u = jwt.Claims.GetValueOrDefault("email",""); }
            if (string.IsNullOrEmpty(u) && jwt.Claims.ContainsKey("emails")) { u = jwt.Claims.GetValueOrDefault("emails",""); }
            if (string.IsNullOrEmpty(u) && jwt.Claims.ContainsKey("upn")) { u = jwt.Claims.GetValueOrDefault("upn",""); }
            return u ?? "";
        } catch { return ""; }
    }

send-request.set-url:
@{
          var dvUrl = "{{d365-dataverse-url}}".TrimEnd('/');
          var id = (string)context.Variables["applicationId"];
          return dvUrl + "/api/data/v9.2/tasks(" + id + ")?$select=activityid,subject,description";
      }

set-variable.value:
@{
        try {
            var body = ((IResponse)context.Variables["dvGet"]).Body.As<JObject>();
            var desc = (string)body["description"] ?? "";
            var upn = (string)context.Variables["citizenUpn"];
            var ownerToken = "citizenUpn: " + upn;
            return desc.Contains(ownerToken + " |") || desc.EndsWith(ownerToken, StringComparison.Ordinal);
        } catch { return false; }
    }

@{
        try {
            var body = ((IResponse)context.Variables["dvGet"]).Body.As<JObject>();
            var desc = (string)body["description"] ?? "";
            var idx = desc.IndexOf("| text:", StringComparison.Ordinal);
            if (idx < 0) { return ""; }
            var json = desc.Substring(idx + 7).Trim();
            JObject parsed;
            try { parsed = JObject.Parse(json); } catch { return ""; }
            var prefix = "https://{{storage-account-name}}.blob.core.windows.net/citizen-uploads/";
            var blobNamePattern = "^[0-9]{8}/[0-9a-f]{32}_[A-Za-z0-9._-]+$";
            if (parsed.Property("documentBlobName") != null) {
                var blobName = (string)parsed["documentBlobName"] ?? "";
                return System.Text.RegularExpressions.Regex.IsMatch(blobName, blobNamePattern)
                    ? prefix + blobName
                    : "";
            }
            var legacyUrl = (string)parsed["documentBlobUrl"] ?? "";
            if (!legacyUrl.StartsWith(prefix, StringComparison.Ordinal)) { return ""; }
            var legacyBlobName = legacyUrl.Substring(prefix.Length);
            return System.Text.RegularExpressions.Regex.IsMatch(legacyBlobName, blobNamePattern)
                ? prefix + legacyBlobName
                : "";
        } catch { return ""; }
    }

send-request.set-url:
@{
          var dvUrl = "{{d365-dataverse-url}}".TrimEnd('/');
          var id = (string)context.Variables["applicationId"];
          return dvUrl + "/api/data/v9.2/tasks(" + id + ")";
      }

return-response.set-body:
@{
          return new JObject {
            ["error"] = "delete_failed",
            ["message"] = context.LastError != null ? context.LastError.Message : "unknown"
          }.ToString();
      }
